// Normalizacao do payload + chave de idempotencia deterministica (SHA-256).
// Roda uma vez para todos os itens recebidos no webhook.
//
// Por que SHA-256 escrito a mao: o sandbox do Code node do n8n bloqueia
// require('crypto') e nao expoe o Web Crypto global, entao a funcao abaixo e
// uma implementacao pura em JS (validada contra o SHA-256 de referencia).
const K = [
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
  0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
  0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
  0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
  0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
  0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
];

const rotr = (x, n) => (x >>> n) | (x << (32 - n));

function utf8Bytes(texto) {
  const out = [];
  for (const ch of Array.from(String(texto))) {
    const c = ch.codePointAt(0);
    if (c < 0x80) out.push(c);
    else if (c < 0x800) out.push(0xc0 | (c >> 6), 0x80 | (c & 0x3f));
    else if (c < 0x10000) out.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 0x3f), 0x80 | (c & 0x3f));
    else out.push(0xf0 | (c >> 18), 0x80 | ((c >> 12) & 0x3f), 0x80 | ((c >> 6) & 0x3f), 0x80 | (c & 0x3f));
  }
  return out;
}

function sha256(texto) {
  const h = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
  const bytes = utf8Bytes(texto);
  const bits = bytes.length * 8;
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);
  const hi = Math.floor(bits / 4294967296);
  const lo = bits >>> 0;
  bytes.push((hi >>> 24) & 255, (hi >>> 16) & 255, (hi >>> 8) & 255, hi & 255);
  bytes.push((lo >>> 24) & 255, (lo >>> 16) & 255, (lo >>> 8) & 255, lo & 255);

  const w = new Array(64);
  for (let i = 0; i < bytes.length; i += 64) {
    for (let t = 0; t < 16; t++) {
      w[t] = (bytes[i + t * 4] << 24) | (bytes[i + t * 4 + 1] << 16) | (bytes[i + t * 4 + 2] << 8) | bytes[i + t * 4 + 3];
    }
    for (let t = 16; t < 64; t++) {
      const s0 = rotr(w[t - 15], 7) ^ rotr(w[t - 15], 18) ^ (w[t - 15] >>> 3);
      const s1 = rotr(w[t - 2], 17) ^ rotr(w[t - 2], 19) ^ (w[t - 2] >>> 10);
      w[t] = (w[t - 16] + s0 + w[t - 7] + s1) | 0;
    }
    let a = h[0], b = h[1], c = h[2], d = h[3], e = h[4], f = h[5], g = h[6], hh = h[7];
    for (let t = 0; t < 64; t++) {
      const S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
      const ch = (e & f) ^ (~e & g);
      const t1 = (hh + S1 + ch + K[t] + w[t]) | 0;
      const S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const t2 = (S0 + maj) | 0;
      hh = g; g = f; f = e; e = (d + t1) | 0;
      d = c; c = b; b = a; a = (t1 + t2) | 0;
    }
    h[0] = (h[0] + a) | 0; h[1] = (h[1] + b) | 0; h[2] = (h[2] + c) | 0; h[3] = (h[3] + d) | 0;
    h[4] = (h[4] + e) | 0; h[5] = (h[5] + f) | 0; h[6] = (h[6] + g) | 0; h[7] = (h[7] + hh) | 0;
  }
  return h.map((x) => (x >>> 0).toString(16).padStart(8, '0')).join('');
}

// Cache de chaves ja processadas (persiste entre execucoes do workflow).
const store = $getWorkflowStaticData('global');
if (!Array.isArray(store.chaves)) store.chaves = [];
const LIMITE_CACHE = 5000;

const saida = [];

for (const item of $input.all()) {
  const b = item.json.body || item.json;

  const canal = String(b.canal || '').trim().toLowerCase();
  const remetente = String(b.remetente || '').trim();
  const texto = String(b.texto || '').trim();
  const idExterno = b.id_evento ? String(b.id_evento) : null;
  const recebidoEm = new Date().toISOString();
  const tsOrigem = b.timestamp ? String(b.timestamp) : recebidoEm;

  // Validacao dos campos obrigatorios
  const faltando = [];
  if (!canal) faltando.push('canal');
  if (!remetente) faltando.push('remetente');
  if (!texto) faltando.push('texto');

  // Chave de idempotencia: id do evento quando existe, senao chave derivada estavel
  const chave = idExterno
    ? sha256(canal + ':' + idExterno)
    : sha256(canal + ':' + remetente + ':' + tsOrigem.slice(0, 16) + ':' + sha256(texto));

  let status = 'novo';
  let motivo = null;

  if (faltando.length) {
    status = 'invalido';
    motivo = 'campos obrigatorios ausentes: ' + faltando.join(', ');
  } else if (store.chaves.includes(chave)) {
    status = 'duplicado';
    motivo = 'chave de idempotencia ja processada';
  } else {
    store.chaves.push(chave);
    if (store.chaves.length > LIMITE_CACHE) {
      store.chaves = store.chaves.slice(-LIMITE_CACHE);
    }
  }

  saida.push({
    json: {
      chave,
      canal,
      remetente,
      texto,
      id_externo: idExterno,
      timestamp_origem: tsOrigem,
      recebido_em: recebidoEm,
      status,
      motivo,
      tentativas: 0,
      http_status: null,
      ultimo_erro: null,
      na_fila_reprocessamento: false,
      payload_original: b,
    },
  });
}

return saida;

// Classifica a resposta do CRM sem lancar excecao.
// 2xx   -> entregue
// 4xx   -> invalido (falha permanente, nao faz retry)
// resto -> retentar (falha transitoria)
//
// O numero da tentativa vem de $runIndex: cada volta no laco de retry executa
// este node de novo, entao runIndex 0 e a 1a tentativa. Usar o contador do
// proprio n8n evita o bug de reiniciar o contador a cada volta.
const tentativa = $runIndex + 1;
const saida = [];

for (const item of $input.all()) {
  const base = $('Normalize payload and build idempotency key').first().json;
  const code = Number(item.json.statusCode || 0);
  const corpo = item.json.body;

  const evento = { ...base };
  evento.http_status = code;
  evento.tentativas = tentativa;

  const detalhe = typeof corpo === 'string'
    ? corpo.slice(0, 500)
    : JSON.stringify(corpo || {}).slice(0, 500);

  if (code >= 200 && code < 300) {
    evento.status = 'entregue';
    evento.motivo = tentativa > 1 ? 'entregue na tentativa ' + tentativa : null;
    evento.ultimo_erro = null;
  } else if (code >= 400 && code < 500) {
    evento.status = 'invalido';
    evento.motivo = 'CRM rejeitou o evento (' + code + '): falha permanente, sem retry';
    evento.ultimo_erro = detalhe;
  } else {
    evento.status = 'retentar';
    evento.motivo = 'falha transitoria no CRM (' + (code || 'sem resposta') + ') na tentativa ' + tentativa;
    evento.ultimo_erro = detalhe;
  }

  saida.push({ json: evento });
}

return saida;

// Fecha o ciclo de vida do evento com um status final explicito.
// Nenhum evento sai daqui sem desfecho.
const FINAIS = ['entregue', 'duplicado', 'invalido', 'falha'];

return $input.all().map((item) => {
  const e = { ...item.json };

  if (e.status === 'retentar') {
    e.status = 'falha';
    e.na_fila_reprocessamento = true;
    e.motivo = 'tentativas de entrega esgotadas (' + e.tentativas + '/3): ' + (e.motivo || '');
  }

  if (!FINAIS.includes(e.status)) {
    e.status = 'falha';
    e.na_fila_reprocessamento = true;
    e.motivo = 'status inesperado ao final do fluxo';
  }

  e.finalizado_em = new Date().toISOString();

  // Chave do registro no ledger: uma linha por (chave de idempotencia, desfecho).
  // Assim um evento duplicado nunca sobrescreve o registro da entrega original.
  e.chave_registro = e.chave + ':' + e.status;

  // A Data Table guarda o payload bruto como texto.
  e.payload_original = typeof e.payload_original === 'string'
    ? e.payload_original
    : JSON.stringify(e.payload_original || {});

  // Normaliza os tipos para as colunas da Data Table (sem null).
  e.tentativas = Number(e.tentativas || 0);
  e.http_status = e.http_status == null ? 0 : Number(e.http_status);
  e.na_fila_reprocessamento = Boolean(e.na_fila_reprocessamento);
  e.motivo = e.motivo == null ? '' : String(e.motivo);
  e.ultimo_erro = e.ultimo_erro == null ? '' : String(e.ultimo_erro);
  e.id_externo = e.id_externo == null ? '' : String(e.id_externo);

  return { json: e };
});

// Monta a mensagem de alerta: canal, chave, status e ultimo erro.
// Enxuto de proposito: quem recebe precisa decidir sem abrir o n8n.
return $input.all().map((item) => {
  const e = item.json;
  const linhas = [
    '[PONTE DE EVENTOS] ' + String(e.status).toUpperCase(),
    'canal: ' + e.canal,
    'remetente: ' + e.remetente,
    'chave: ' + e.chave,
    'tentativas: ' + e.tentativas,
    'http: ' + (e.http_status === null ? '-' : e.http_status),
    'motivo: ' + (e.motivo || '-'),
    'erro: ' + (e.ultimo_erro || '-'),
    'fila de reprocessamento: ' + (e.na_fila_reprocessamento ? 'sim' : 'nao'),
  ];
  return { json: { alerta: linhas.join('\n'), evento: e } };
});
